        int defectiveLaptops = sc.nextInt();

        // Create Helper object
        Helper h = new Helper(laptopModel, totalLaptops, costPerLaptop, defectiveLaptops);

        // Display report
        ProductionMonitor.display(h);

        sc.close();
    }
}
```

