// Example of proper package structure and class design

// File: com/example/Helper.java
package com.example;

public class Helper {
    private String laptopModel;
    private int totalLaptops;
    private double costPerLaptop;
    private int defectiveLaptops;

    // Constructor
    public Helper(String model, int total, double cost, int defective) {
        this.laptopModel = model;
        this.totalLaptops = total;
        this.costPerLaptop = cost;
        this.defectiveLaptops = defective;
    }

    // Getters
    public String getLaptopModel() { return laptopModel; }
    public int getTotalLaptops() { return totalLaptops; }
    public double getCostPerLaptop() { return costPerLaptop; }
    public int getDefectiveLaptops() { return defectiveLaptops; }

    // Calculations
    public double calculateTotalCost() {
        return totalLaptops * costPerLaptop;
    }

    public double calculateEfficiency() {
        int goodLaptops = totalLaptops - defectiveLaptops;
        return (double) goodLaptops / totalLaptops * 100;
    }
}
```

